        {
            foreach(var asset in home.assets){if(string.IsNullOrWhiteSpace(asset.resourcePath) || !Hashes.ContainsKey(asset.resourcePath))throw new ArgumentException("Unaccepted production asset: "+asset.id);asset.placeholder=false;}
